    localparam [55:0] VOL0_VEC = {7'd12, 7'd1, 7'd0, 7'd0, 7'd0, 7'd0, 7'd0, 7'd0};  // 0%
    localparam [55:0] VOL1_VEC = {7'd12, 7'd6, 7'd3, 7'd0, 7'd0, 7'd0, 7'd0, 7'd0};  // 25%
