        font_rom[1298] = 8'h20;
        font_rom[1299] = 8'h48;
        font_rom[1300] = 8'h7E;
        font_rom[1301] = 8'h08;
        font_rom[1302] = 8'h0E;
        font_rom[1303] = 8'hF9;
        font_rom[1304] = 8'h4A;
        font_rom[1305] = 8'h1F;
        font_rom[1306] = 8'h10;
        font_rom[1307] = 8'h10;
        font_rom[1308] = 8'h1F;
        font_rom[1309] = 8'h10;
        font_rom[1310] = 8'h10;
        font_rom[1311] = 8'h1F;
        font_rom[1312] = 8'h0C;
        font_rom[1313] = 8'hF0;
        font_rom[1314] = 8'h80;
        font_rom[1315] = 8'h80;
        font_rom[1316] = 8'hFE;
        font_rom[1317] = 8'h88;
        font_rom[1318] = 8'h88;
        font_rom[1319] = 8'h08;
        font_rom[1320] = 8'h08;
        font_rom[1321] = 8'hF8;
        font_rom[1322] = 8'h10;
        font_rom[1323] = 8'h10;
        font_rom[1324] = 8'hF0;
        font_rom[1325] = 8'h10;
        font_rom[1326] = 8'h10;
        font_rom[1327] = 8'hF0;
        font_rom[1328] = 8'h10;
        font_rom[1329] = 8'h10;
        font_rom[1330] = 8'h17;
        font_rom[1331] = 8'h20;
        font_rom[1332] = 8'h23;
        font_rom[1333] = 8'h62;
        font_rom[1334] = 8'h63;
        font_rom[1335] = 8'hA0;
        font_rom[1336] = 8'h2F;
        font_rom[1337] = 8'h28;
        font_rom[1338] = 8'h23;
        font_rom[1339] = 8'h20;
        font_rom[1340] = 8'h20;
        font_rom[1341] = 8'h20;
        font_rom[1342] = 8'h21;
        font_rom[1343] = 8'h20;
        font_rom[1344] = 8'h80;
        font_rom[1345] = 8'h40;
        font_rom[1346] = 8'hFC;
        font_rom[1348] = 8'hF8;
        font_rom[1349] = 8'h08;
        font_rom[1350] = 8'hF8;
        font_rom[1352] = 8'hFE;
        font_rom[1353] = 8'h02;
        font_rom[1354] = 8'hF8;
        font_rom[1355] = 8'h40;
        font_rom[1356] = 8'h40;
        font_rom[1357] = 8'h40;
        font_rom[1358] = 8'h40;
        font_rom[1359] = 8'h80;
    end

    // ----------------------------------------- parameter codes and trigger
    wire [2:0] vol_code = (volume >= 8'd224) ? 3'd4 :
                          (volume >= 8'd160) ? 3'd3 :
                          (volume >= 8'd96)  ? 3'd2 :
                          (volume >= 8'd32)  ? 3'd1 : 3'd0;
    // 0..3 = 25 / 50 / 75 / 100 %
    wire [1:0] bri_code = (brightness >= 8'd224) ? 2'd3 :
                          (brightness >= 8'd160) ? 2'd2 :
                          (brightness >= 8'd96)  ? 2'd1 : 2'd0;

    reg vs_q;
    wire frame_start = vs_q && !vsync;
    reg [2:0] vol_q;
    reg [1:0] bri_q;
    reg auto_q;
    reg [1:0] period_q;
    reg paused_q;
    reg [7:0] arm_count;
    reg [8:0] show_count;
    reg [2:0] hl_row;              // 1 volume, 2 brightness, 3 auto, 4 period

    assign panel_visible = (show_count != 0);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            vs_q <= 1'b1;
            vol_q <= 3'd0;
            bri_q <= 2'd0;
            auto_q <= 1'b0;
            period_q <= 2'd0;
            paused_q <= 1'b0;
            arm_count <= ARM_FRAMES;
            show_count <= 9'd0;
            hl_row <= 3'd7;
        end else begin
            vs_q <= vsync;
            if (frame_start) begin
                vol_q <= vol_code;
                bri_q <= bri_code;
                auto_q <= auto_enabled;
                period_q <= period_code;
                paused_q <= music_paused;

                if (suppress)
                    arm_count <= ARM_FRAMES;
                else if (arm_count != 0)
                    arm_count <= arm_count - 1'b1;

                if (suppress || arm_count != 0) begin
                    show_count <= 9'd0;
                end else if (vol_code != vol_q) begin
                    hl_row <= 3'd1;
                    show_count <= SHOW_FRAMES;
                end else if (bri_code != bri_q) begin
                    hl_row <= 3'd2;
                    show_count <= SHOW_FRAMES;
                end else if (auto_enabled != auto_q) begin
                    hl_row <= 3'd3;
                    show_count <= SHOW_FRAMES;
                end else if (period_code != period_q) begin
                    hl_row <= 3'd4;
                    show_count <= SHOW_FRAMES;
                end else if (music_paused != paused_q) begin
                    hl_row <= 3'd6;
                    show_count <= SHOW_FRAMES;
                end else if (show_count != 0) begin
                    show_count <= show_count - 1'b1;
                end
            end
        end
    end

    // -------------------------------------------------------- line tracking
    reg [11:0] line_y;
    reg de_q;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            line_y <= 12'd0;
            de_q <= 1'b0;
        end else begin
            de_q <= de;
            if (!vsync)
                line_y <= 12'd0;
            else if (de_q && !de)
                line_y <= line_y + 1'b1;
        end
    end

    // Per-line row decode. line_y only changes at the end of an active line,
    // so these quasi-static stages settle long before the next line starts.
    wire [11:0] ly_rel = line_y - PANEL_Y;
    reg [8:0] py_q;              // line in_panel the panel
    reg in_py_q;
    reg [8:0] by_q;              // line in_panel the row area
    reg [2:0] row_q;             // 0..6, 7 = below the last row
    reg [4:0] row_y_q;           // 0..27 in_panel the row
    always @(posedge clk) begin
        py_q <= ly_rel[8:0];
        in_py_q <= (ly_rel < PH);
        by_q <= py_q - TITLE_H;
        row_q <= (by_q >= 9'd196) ? 3'd7 :
                 (by_q >= 9'd168) ? 3'd6 :
                 (by_q >= 9'd140) ? 3'd5 :
                 (by_q >= 9'd112) ? 3'd4 :
                 (by_q >= 9'd84)  ? 3'd3 :
                 (by_q >= 9'd56)  ? 3'd2 :
                 (by_q >= 9'd28)  ? 3'd1 : 3'd0;
        case (row_q)
            3'd0: row_y_q <= by_q[4:0];
            3'd1: row_y_q <= by_q - 9'd28;
            3'd2: row_y_q <= by_q - 9'd56;
            3'd3: row_y_q <= by_q - 9'd84;
            3'd4: row_y_q <= by_q - 9'd112;
            3'd5: row_y_q <= by_q - 9'd140;
            default: row_y_q <= by_q - 9'd168;
        endcase
    end
    wire body_q = (py_q >= TITLE_H);

    // ------------------------------------------------------ pixel pipeline
    // P1: panel-relative column of the pixel LOOKAHEAD clocks ahead.
    reg [9:0] xr_p1;
    reg in_px_p1;
    wire [9:0] nx = pixel_x + LOOKAHEAD;
    wire [9:0] xr_now = nx - PANEL_X;
    always @(posedge clk) begin
        xr_p1 <= xr_now;
        in_px_p1 <= (xr_now < PW);
    end

    // P2: classify the pixel and locate its text slot.
    localparam [2:0] CLS_NONE = 3'd0, CLS_BORDER = 3'd1, CLS_TITLE = 3'd2,
                     CLS_BODY = 3'd3, CLS_HLBAR = 3'd4, CLS_STRIPE = 3'd5,
                     CLS_DIVIDER = 3'd6;
    reg [2:0] cls_p2;
    reg [1:0] kind_p2;           // 0 none, 1 label, 2 value, 3 title
    reg [2:0] slot_p2;
    reg [2:0] gcol_p2;
    reg [3:0] grow_p2;
    reg hl_p2;
    wire in_panel = in_px_p1 && in_py_q;
    wire [9:0] lx = xr_p1 - LBL_X;
    wire [9:0] vx = xr_p1 - VAL_X;
    wire [9:0] tx = xr_p1 - TITLE_X;
    wire [8:0] row_text_y = {4'b0, row_y_q} - 9'd6;
    wire [8:0] title_text_y = py_q - 9'd6;
    wire row_hl = (row_q == hl_row) && (row_q != 3'd7);
    always @(posedge clk) begin
        cls_p2 <= CLS_NONE;
        kind_p2 <= 2'd0;
        slot_p2 <= 3'd0;
        gcol_p2 <= 3'd0;
        grow_p2 <= 4'd0;
        hl_p2 <= row_hl;
        if (in_panel) begin
            if (xr_p1 < 10'd2 || xr_p1 >= PW - 2 || py_q < 9'd2 || py_q >= PH - 2)
                cls_p2 <= CLS_BORDER;
            else if (!body_q)
                cls_p2 <= CLS_TITLE;
            else if (py_q == TITLE_H)
                cls_p2 <= CLS_DIVIDER;
            else if (row_hl && row_y_q >= 5'd1 && row_y_q < 5'd27 &&
                     xr_p1 >= 10'd8 && xr_p1 < PW - 8)
                cls_p2 <= (xr_p1 < 10'd12) ? CLS_STRIPE : CLS_HLBAR;
            else
                cls_p2 <= CLS_BODY;

            if (!body_q) begin
                // Title text is drawn at 2x.
                if (tx < 10'd64 && py_q >= 9'd6 && py_q < 9'd38) begin
                    kind_p2 <= 2'd3;
                    slot_p2 <= {1'b0, tx[5:4]};
                    gcol_p2 <= tx[3:1];
                    grow_p2 <= title_text_y[4:1];
                end
            end else if (row_q != 3'd7 && row_y_q >= 5'd6 && row_y_q < 5'd22) begin
                if (lx < 10'd64) begin
                    kind_p2 <= 2'd1;
                    slot_p2 <= lx[5:3];
                    gcol_p2 <= lx[2:0];
                    grow_p2 <= row_text_y[3:0];
                end else if (vx < 10'd64) begin
                    kind_p2 <= 2'd2;
                    slot_p2 <= vx[5:3];
                    gcol_p2 <= vx[2:0];
                    grow_p2 <= row_text_y[3:0];
                end
            end
        end
    end

    // Text strings for the current row. They only change with the row (once
    // per line) or with a parameter, so they are registered in two quasi-static
    // stages ahead of the pixel pipeline: codes first, then the string vectors.
    reg [2:0] vol_r, bri_r;
    reg [1:0] per_r;
    reg auto_r, music_r;
    reg [1:0] idx_r;
    always @(posedge clk) begin
        vol_r <= vol_code;
        bri_r <= {1'b0, bri_code};
        per_r <= period_code;
        auto_r <= auto_enabled;
        music_r <= music_on;
        idx_r <= active_index;
    end

    reg [55:0] label_vec;
    always @(posedge clk) begin
        case (row_q)
            3'd0: label_vec = LBL0_VEC;
            3'd1: label_vec = LBL1_VEC;
            3'd2: label_vec = LBL2_VEC;
            3'd3: label_vec = LBL3_VEC;
            3'd4: label_vec = LBL4_VEC;
            3'd5: label_vec = LBL5_VEC;
            3'd6: label_vec = LBL6_VEC;
            default: label_vec <= 56'd0;
        endcase
    end
    wire [6:0] cur_digit = 1 + 7'd1 + {5'd0, idx_r};
    reg [55:0] vol_vec, bri_vec, auto_vec, per_vec, music_vec;
    always @(posedge clk) begin
        vol_vec <= (vol_code == 0) ? VOL0_VEC : (vol_code == 1) ? VOL1_VEC : (vol_code == 2) ? VOL2_VEC : (vol_code == 3) ? VOL3_VEC : VOL4_VEC;
        bri_vec <= (bri_code == 0) ? BRI0_VEC : (bri_code == 1) ? BRI1_VEC : (bri_code == 2) ? BRI2_VEC : BRI3_VEC;
        auto_vec <= auto_enabled ? AUTO1_VEC : AUTO0_VEC;
        per_vec <= (period_code == 0) ? PER0_VEC : (period_code == 1) ? PER1_VEC : (period_code == 2) ? PER2_VEC : PER3_VEC;
        music_vec <= music_paused ? MUS2_VEC : (music_on ? MUS1_VEC : MUS0_VEC);
    end
    reg [55:0] value_vec;
    always @(posedge clk) begin
        case (row_q)
            3'd0: value_vec <= {7'd5, 7'd0, 7'd11, 7'd0, cur_digit, 7'd0, 7'd0, 7'd0};
            3'd1: value_vec <= vol_vec;
            3'd2: value_vec <= bri_vec;
            3'd3: value_vec <= auto_vec;
            3'd4: value_vec <= per_vec;
            3'd5: value_vec <= TRANS_VEC;
            default: value_vec <= music_vec;
        endcase
    end

    // P3: pick the half glyph for the slot.
    wire [55:0] pick_vec = (kind_p2 == 2'd3) ? TITLE_VEC :
                           (kind_p2 == 2'd2) ? value_vec : label_vec;
    reg [6:0] half_p3;
    reg [2:0] cls_p3;
    reg [1:0] kind_p3;
    reg [2:0] gcol_p3;
    reg [3:0] grow_p3;
    reg hl_p3;
    always @(posedge clk) begin
        half_p3 <= (kind_p2 == 2'd0) ? 7'd0 : pick_vec[slot_p2 * 7 +: 7];
        cls_p3 <= cls_p2;
        kind_p3 <= kind_p2;
        gcol_p3 <= gcol_p2;
        grow_p3 <= grow_p2;
        hl_p3 <= hl_p2;
    end

    // P4: font ROM read.
    reg [7:0] glyph_p4;
    reg [2:0] cls_p4;
    reg [1:0] kind_p4;
    reg [2:0] gcol_p4;
    reg hl_p4;
    always @(posedge clk) begin
        glyph_p4 <= font_rom[{half_p3, grow_p3}];
        cls_p4 <= cls_p3;
        kind_p4 <= kind_p3;
        gcol_p4 <= gcol_p3;
        hl_p4 <= hl_p3;
    end

    // P5: resolve the colour. mode 0 = pass through, 1 = solid, 2 = dim the
    // picture to a quarter and add the colour (panel body stays translucent).
    localparam [23:0] COL_GOLD = 24'hC9A24D;
    reg [1:0] mode_p5;
    reg [23:0] col_p5;
    wire text_bit = (kind_p4 != 2'd0) && glyph_p4[~gcol_p4];
    wire show = panel_visible && !suppress;
    always @(posedge clk) begin
        mode_p5 <= 2'd0;
        col_p5 <= 24'd0;
        if (show && cls_p4 != CLS_NONE) begin
            mode_p5 <= 2'd1;
            if (text_bit) begin
                if (kind_p4 == 2'd3)
                    col_p5 <= 24'hF0C060;
                else if (kind_p4 == 2'd2 && hl_p4)
                    col_p5 <= 24'hF2C25A;
                else if (kind_p4 == 2'd2)
                    col_p5 <= 24'hFFFFFF;
                else
                    col_p5 <= 24'hE2DDD6;
            end else begin
                case (cls_p4)
                    CLS_BORDER:  col_p5 <= COL_GOLD;
                    CLS_DIVIDER: col_p5 <= COL_GOLD;
                    CLS_STRIPE:  col_p5 <= 24'hE0B04A;
                    CLS_HLBAR:   col_p5 <= 24'h6B1B22;
                    CLS_TITLE: begin
                        mode_p5 <= 2'd2;
                        col_p5 <= 24'h2A1618;
                    end
                    default: begin
                        mode_p5 <= 2'd2;
                        col_p5 <= 24'h121216;
                    end
                endcase
            end
        end
    end

    wire [23:0] dimmed = {2'b00, rgb_in[23:18], 2'b00, rgb_in[15:10], 2'b00, rgb_in[7:2]};
    wire [23:0] blended = {dimmed[23:16] + col_p5[23:16],
                           dimmed[15:8] + col_p5[15:8],
                           dimmed[7:0] + col_p5[7:0]};
    assign rgb_out = (mode_p5 == 2'd1) ? col_p5 :
                     (mode_p5 == 2'd2) ? blended : rgb_in;
endmodule
